-- Options des packs véhicule, comme chez LedPerf (9 novembre 2026).
-- Second relevé : les options posées directement sur le produit (finition
-- claire / fumée des clignotants dynamiques, couleur, intensité…), que le
-- premier relevé ne lisait pas.
--
-- Demande de l'exploitant : « récupère toutes les options (type ballast,
-- couleur, etc.) pour tous les produits ». Relevé du configurateur LedPerf
-- dans le navigateur de l'exploitant : pour chaque famille de produit, les
-- listes (type de ballast, température de couleur…) et le prix de chaque
-- combinaison. Prix LEDVROOM : le barème du catalogue appliqué au prix de la
-- combinaison. Stock : 10 par combinaison.
--
-- Une combinaison = une variante, nommée « Libellé : valeur · Libellé :
-- valeur » : la fiche en tire une liste déroulante par option (BuyBox). La
-- variante existante devient la combinaison par défaut (même identifiant :
-- paniers et compatibilités restent valables) ; les autres sont créées, avec
-- les mêmes compatibilités. 3881 fiches, 8429 combinaisons.

DROP TABLE IF EXISTS "_opt";
CREATE TEMPORARY TABLE "_opt" AS
SELECT x.*, p."id" AS pid,
  (SELECT v."id" FROM "ProductVariant" v WHERE v."productId" = p."id" AND v."active" ORDER BY v."position", v."createdAt" LIMIT 1) AS v0
