-- Fiches qui ont déjà plusieurs variantes (conditionnements) : on n'y touche pas.
DELETE FROM "_opt" o WHERE (SELECT COUNT(*) FROM "ProductVariant" v
  WHERE v."productId" = o.pid AND v."active" AND v."name" NOT LIKE '% : %') > 1;
DELETE FROM "_opt" o WHERE o.v0 IS NULL;

-- La variante existante devient la combinaison par défaut.
UPDATE "ProductVariant" v SET "name" = o.n, "priceCents" = o.c, "position" = 0, "updatedAt" = NOW()
FROM "_opt" o WHERE o.o = 0 AND v."id" = o.v0;

INSERT INTO "ProductVariant" ("id", "productId", "sku", "name", "packaging", "priceCents", "vatRateId", "stockOnHand", "position", "createdAt", "updatedAt")
SELECT 'opv' || substr(md5(o.pid || ':' || o.n), 1, 22), o.pid, v."sku" || '-O' || o.o, o.n, v."packaging", o.c, v."vatRateId", 10, o.o, NOW(), NOW()
FROM "_opt" o JOIN "ProductVariant" v ON v."id" = o.v0
WHERE o.o > 0
ON CONFLICT DO NOTHING;

INSERT INTO "StockMovement" ("id", "variantId", "delta", "reason", "reference", "createdAt")
SELECT 'ops' || substr(md5('m:' || o.pid || ':' || o.n), 1, 22), 'opv' || substr(md5(o.pid || ':' || o.n), 1, 22), 10, 'import', 'catalogue:options', NOW()
FROM "_opt" o
WHERE o.o > 0 AND EXISTS (SELECT 1 FROM "ProductVariant" v WHERE v."id" = 'opv' || substr(md5(o.pid || ':' || o.n), 1, 22))
ON CONFLICT ("id") DO NOTHING;

-- Mêmes compatibilités que la variante de départ.
INSERT INTO "Fitment" ("id", "configurationId", "positionId", "variantId", "status", "quantity", "restrictions",
  "roadApproval", "approvalMarket", "approvalNote", "source", "verifiedAt", "verifiedBy", "createdAt", "updatedAt")
SELECT 'opf' || substr(md5(f."id" || ':' || o.n), 1, 22), f."configurationId", f."positionId",
  'opv' || substr(md5(o.pid || ':' || o.n), 1, 22), f."status", f."quantity", f."restrictions",
  f."roadApproval", f."approvalMarket", f."approvalNote", f."source", f."verifiedAt", f."verifiedBy", NOW(), NOW()
FROM "_opt" o JOIN "Fitment" f ON f."variantId" = o.v0
WHERE o.o > 0 AND EXISTS (SELECT 1 FROM "ProductVariant" v WHERE v."id" = 'opv' || substr(md5(o.pid || ':' || o.n), 1, 22))
ON CONFLICT DO NOTHING;

DROP TABLE "_opt";
